'use strict';
/* 픽스처 — `tools/가드계수.js` 의 «탐지력»을 값으로 못박는 재료다. 돌아가지 않는다(파일명에
 * `.test.js` 를 안 붙인 것도 그래서다 — 붙이면 러너가 실행하려 든다).
 * 한 파일에 네 모양을 일부러 섞어 둔다: 세야 하는 둘, 세면 «안 되는» 둘. */

const fs = require('fs');
const assert = require('assert');

// ① 세야 한다 — 주석 제거기 지역 사본 1벌
const 주석제거 = (s) => s.replace(/\/\*[\s\S]*?\*\//g, ' ');

// ② 세면 «안 된다» — base64url 인코더다(급조 계수기가 이걸 사본으로 셌다 · F401)
const b64 = (o) => String(o).replace(/\+/g, '-').replace(/\//g, '_');

const 소스 = fs.readFileSync('없는파일.js', 'utf8');

// ③ 세야 한다 — 부정 단언 × 파일 원문 «직접»
assert.ok(!소스.includes('평균'));

// ④ 세야 한다(안전 쪽) — 부정 단언 × 정제 경유
assert.equal(주석제거(소스).includes('등수'), false);

// ⑤ 세면 «안 된다» — 수신자가 문자열 상수다(급조 계수기가 이걸 위험으로 셌다)
assert.ok(!'등수는 안 쓴다'.includes('평균'));

/* ⑥ 이 뿌리가 재는 ㉠«부정» 축에는 안 든다 — 긍정 단언이다.
 * ⚠ 2026-08-18(F602) 부터 이것은 «존재» 축의 `존재위험` 으로는 선다. 그 축의 탐지력은
 *   뿌리가 따로다(`fixtures/가드계수존재`) — 여기 숫자를 흔들지 않으려고 나눴다. */
assert.ok(소스.includes('export'));

/* ── 2026-08-13 2차 · 계수기가 «함수 모양»만 보던 사각 (F401 잔여 처분에서 실측) ──────────
 * 아래 둘은 저장소의 사본 «다수»가 실제로 쓰던 모양인데 첫 판이 통째로 못 봤다.
 * 그래서 「지역 사본 0벌」이 나왔고 회귀가 13벌이 산 채로 초록이었다. */

// ⑦ 세야 한다 — «식» 모양 사본(함수가 아니라 값이다)
const 주석뺀소스 = 소스.replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/(^|[^:])\/\/[^\n]*/g, '$1');
// ⑦-b 그 파생은 «정제»다 — 원문을 직접 재는 자리가 아니므로 위험이 아니다
assert.ok(!주석뺀소스.includes('등수'));

// ⑧ 세야 한다 — «함수 선언» 모양 사본
function 주석없이(s) {
  return s.replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/(^|[^:])\/\/[^\n]*/g, '$1 ');
}
assert.equal(주석없이(소스).includes('석차'), false);

// ⑨ 세면 «안 된다» — 식 모양이지만 주석이 아니라 «공백»을 지운다(거짓양성 축)
const 납작 = 소스.replace(/\s+/g, ' ');
assert.ok(!납작.includes('평균점'));

/* ⑩ 위험이 아니라 ❔모름이어야 한다 — **한 이름이 두 뜻**이다.
 * 이 도구는 파일 전체를 한 스코프로 근사해서, 아래 두 `두뜻` 을 못 가른다. 못 가른 것을
 * 조용히 위험으로 세면 처방(「공용 통로로 감싸라」)이 **상수를 감싸라**는 말이 된다(F103).
 * (실측 자리 = `tests/기기비우기.test.js` — 탐지력 픽스처가 상수를 넘기는 모양이었다.) */
const 두뜻 = fs.readFileSync('없는파일2.js', 'utf8');
assert.ok(!두뜻.includes('평균1'));

function 픽스처판() {
  const 두뜻 = '상수 판 — 파일이 아니다';
  assert.ok(!두뜻.includes('평균2'));
}

/* ── 2026-08-13 3차 · 별표는 주석이 아니다 (as 저장소에 처음 대 보고 실측) ──────────────
 * 아래 셋은 정규식에 `\*` 가 들어 있지만 **주석과 아무 상관이 없다.** 옛 판정은 `\*` 하나만
 * 보고 셋을 전부 사본으로 셌다 — 블록 주석은 `\/\*` 라 **슬래시가 있어야 주석이다.**
 * 🔑 이 셋은 talk 에 없는 모양이라 여기서는 «영원히» 안 드러났다(조여도 talk 은 0벌 그대로).
 *    as 실측 = 사본 44 중 **24벌이 이 거짓양성**. 계수기를 다른 저장소에 대 본 것이 곧 탐지였다.
 * ⚠ 단언을 안 붙인다 — 붙이면 ㉠축(위험/안전/모름)의 숫자가 흔들려 이 픽스처가 재는 것이
 *    ㉡축 하나라는 사실이 흐려진다. 여기서 재는 것은 «사본 목록에 안 드는가» 하나뿐이다. */

// ⑪ 세면 «안 된다» — 마크다운 굵게(`**`)를 지운다
const 별표없이 = 소스.replace(/\*\*/g, '').replace(/\*/g, '');

// ⑫ 세면 «안 된다» — glob 을 정규식으로 바꾼다(`*` → `.*`)
const globRe = new RegExp('^' + '문서/*.md'.replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*') + '$');

module.exports = { b64, 주석없이, 픽스처판, 별표없이, globRe };
